    "description": "裹糖烘烤的圆筒糕点；市场和小食店常见。与油炸兰戈什不同，这是裹糖烘烤的甜糕点。比较蛋糕或糕点时，可以分别关注外皮是否酥脆、内馅是否厚重、奶油与果味的比例，以及一份的大小。现烤、冷藏和常温供应会带来不同口感；先尝一小份，再决定是否购买适合携带的包装。",
