        "text": "匈牙利首都，沿多瑙河展开。布达山坡上的城堡与佩斯的议会大厦隔河相望，温泉浴场也是城市日常的一部分。\n\n重要的国际及国内铁路枢纽，靠近 M2 / M4 地铁。"
