        "title": "比较原料、加工与吃法",
        "text": "香肠、熟成肉与鲜肉的制作和食用方法不同。先看原料、是否需要加热、切片厚薄与调味，再判断它适合作为正餐、面包配食还是冷盘；保存条件和携带方式应按具体包装确认。"
