    "description": "巨大的城市公园，包含草地、河流与啤酒花园；标记位于公园南部。从入口到水岸、林荫路或开阔草地，留意不同空间如何被步行者、骑行者和休憩的人使用。与只找一个拍照点相比，选一小段完整步行路线，更能理解公园与周边街区的关系。",
