    "note": "口味比较：与普通汽水比较时留意咖啡因标示、糖分和容量；不同系列不可混作一款。 购买线索：超市、饮料店或餐饮渠道可寻找；不同城市覆盖不同。 保存与包装：玻璃瓶可能涉及押金，具体看包装。\n\n点单时分别确认杯量、咖啡浓度、奶或奶泡以及是否加糖。当地名称能帮助理解常见搭配，却不能代替这一家店的实际配方；先看菜单说明，才能比较不同饮品的口感与价格。\n\n“fritz-kola”：对应企业 / 品牌；““能刷卡”也可能有卡种差异”：支付与币种提醒。这些关联用于比较作品、食物、人物或地点之间的联系，具体内容可在下方关联卡片中继续阅读。",
