  "person-einstein": {
    "description": "物理学家，以相对论等工作著称，曾在柏林工作。他的生平跨越多个国家。爱因斯坦于 1879 年出生在乌尔姆，后来在瑞士、德国和美国等地生活。他在 1914—1933 年间以柏林为重要工作基地，科学网络与政治变动都影响了这段经历。他的 1921 年诺贝尔物理学奖尤其表彰对光电效应定律的发现，不宜简单说成“因为相对论获奖”。",
    "note": "爱因斯坦于 1879 年出生在乌尔姆，后来在瑞士、德国和美国等地生活。他在 1914—1933 年间以柏林为重要工作基地，科学网络与政治变动都影响了这段经历。\n他的 1921 年诺贝尔物理学奖尤其表彰对光电效应定律的发现，不宜简单说成“因为相对论获奖”。相对论与量子理论相关研究都是理解他的科学贡献的线索，但两者所处理的问题并不相同。\n1933 年纳粹上台后，他没有返回德国，之后在美国长期工作。柏林的人物关联说明一段科研与生活史，不能把城市里所有以他命名的机构都视作他本人办公过的原址。\n\n不要只记住名字和一个成就，也可以沿作品、研究方法或公共活动理解其影响。出生、求学、工作和后世纪念所对应的地点不同；人物与场馆的关联帮助建立阅读路径，不自动证明每处都是故居或亲自到访之地。\n\n“柏林与波恩：首都为什么有两段故事？”：把科研生涯放回柏林历史；“玛丽·斯克沃多夫斯卡-居里 · 从华沙到研究世界”：继续认识不同领域的研究者。这些关联用于比较作品、食物、人物或地点之间的联系，具体内容可在下方关联卡片中继续阅读。",
    "reading": [
      {
        "title": "背景与辨别",
        "text": "爱因斯坦于 1879 年出生在乌尔姆，后来在瑞士、德国和美国等地生活。他在 1914—1933 年间以柏林为重要工作基地，科学网络与政治变动都影响了这段经历。\n他的 1921 年诺贝尔物理学奖尤其表彰对光电效应定律的发现，不宜简单说成“因为相对论获奖”。相对论与量子理论相关研究都是理解他的科学贡献的线索，但两者所处理的问题并不相同。\n1933 年纳粹上台后，他没有返回德国，之后在美国长期工作。柏林的人物关联说明一段科研与生活史，不能把城市里所有以他命名的机构都视作他本人办公过的原址。"
      },
      {
        "title": "从生平走向作品与地方联系",
        "text": "不要只记住名字和一个成就，也可以沿作品、研究方法或公共活动理解其影响。出生、求学、工作和后世纪念所对应的地点不同；人物与场馆的关联帮助建立阅读路径，不自动证明每处都是故居或亲自到访之地。"
      },
      {
        "title": "沿这些线索继续了解",
        "text": "“柏林与波恩：首都为什么有两段故事？”：把科研生涯放回柏林历史；“玛丽·斯克沃多夫斯卡-居里 · 从华沙到研究世界”：继续认识不同领域的研究者。这些关联用于比较作品、食物、人物或地点之间的联系，具体内容可在下方关联卡片中继续阅读。"
      }
    ]
  },
