        "text": "特斯拉于 1856 年出生在斯米连，当时属于奥地利帝国，今天位于克罗地亚；他有塞尔维亚族家庭背景，后来长期在美国工作。出生地、文化认同、国籍和职业地点不能当成同一个字段。\n他的研究与交流电系统、电机和高频电学等有关，但现代电力系统由许多发明者、工程师和企业共同发展，不能说他一人“发明了全部交流电”。特斯拉与爱迪生的竞争故事也常被后来的传播简化。\n贝尔格莱德的博物馆保存其遗产与档案，是这张卡的明确城市关联，并不意味着他在贝尔格莱德出生或长期完成全部研究。机场命名、纪念机构与本人实际生活地点应分别理解。"
