        "text": "不要只记住名字和一个成就，也可以沿作品、研究方法或公共活动理解其影响。出生、求学、工作和后世纪念所对应的地点不同；人物与场馆的关联帮助建立阅读路径，不自动证明每处都是故居或亲自到访之地。"
