        "text": "“维也纳城市公园”：寻找音乐纪念线索；“华尔兹为什么既是舞蹈，也是城市名片？”：理解舞曲与城市生活。这些关联用于比较作品、食物、人物或地点之间的联系，具体内容可在下方关联卡片中继续阅读。"
