    "description": "日常购药查询附近正规药店，处方药和持续不适请咨询药师或医疗机构。地图辅助找位置；营业、库存与处方要求需电话或现场确认。先确认要找的是正规药房与相应服务，再准备药品通用名、现用药清单及必要处方。值班安排和处方要求应向当地专业人员核实；这类卡片提供查找与沟通线索，不替代医疗判断。",
