        "text": "阅读时可以区分事实发生的年代、涉及的地域和今天能够看到的遗迹或纪念方式。一个故事的文化意义与某个说法是否有史料支持，是不同问题；沿下方人物、场所或历史卡片继续比较，更容易建立完整脉络。"
