        "text": "“瓦尔特·格罗皮乌斯 · 从学校到现代设计”：认识首任校长；“新艺术、分离派、维也纳工坊有什么区别？”：比较更早的工艺与设计探索；“康定斯基”：认识与学校有关的艺术家。这些关联用于比较作品、食物、人物或地点之间的联系，具体内容可在下方关联卡片中继续阅读。"
