        "text": "“慕尼黑宫廷啤酒屋”：比较常设啤酒馆与节庆帐篷；“慕尼黑的宫殿，和哪一个王朝有关？”：认识王室婚礼的历史背景；“同一个面包，叫法可能不同”：理解饮食词汇的区域差异。这些关联用于比较作品、食物、人物或地点之间的联系，具体内容可在下方关联卡片中继续阅读。"
