        "text": "“慕尼黑大学主楼”：从大学空间继续了解；“人行道上的黄铜小牌，在提醒什么？”：比较城市中的纪念形式。这些关联用于比较作品、食物、人物或地点之间的联系，具体内容可在下方关联卡片中继续阅读。"
