        "title": "沿这些线索继续了解",
        "text": "“无锡博物院”：从地方史展陈继续看；“清名桥历史文化街区”：联系水运与生产空间；“运河怎样把江南城市连成一张网？”：认识区域交通条件。这些关联用于比较作品、食物、人物或地点之间的联系，具体内容可在下方关联卡片中继续阅读。"
