        "text": "“贝尔格莱德为什么守在两河交汇处？”：继续认识当地文化；“一座要塞，为什么有不同帝国的痕迹？”：继续认识当地文化；“Hvala：这串辅音其实是“谢谢””：相关语言趣闻。这些关联用于比较作品、食物、人物或地点之间的联系，具体内容可在下方关联卡片中继续阅读。"
