    "description": "C / F 型插座，230V、50Hz。中国常见三扁脚插头不能默认直接使用，需要合适的转换插头。查看充电器铭牌：支持 100–240V 的设备通常只需转换插头；转换插头不负责变压。大功率电器、吹风机及接地设备需要额外核对电压、功率与接地要求，不要把插头能插入当成电器一定适用。",
