    "note": "德拉瓦河畔的重要城市，Lent 老城区、葡萄种植传统与附近的波霍列山地，让城市漫步和周边自然可以相互衔接。\n\n位于 Lent 一带的表演机构，提供木偶与其他舞台作品。\n\n演出语言、年龄建议、日期和票务以当期节目为准，不把木偶剧一概视为没有年龄区分的儿童节目。 坐标用于辨认位置，非精确入口；开放、预约、施工与具体服务按官方最新说明确认。\n\n欣赏建筑、参加导览与观看演出各有重点。看演出时可先了解作品、演出语言与座位视线；看建筑则注意观众厅与公共空间的组织。演出票和导览票是否互通，应在订票页面分别确认。\n\n“马里博尔 · 河流、气候与日常预算”：把地点放回城市环境。这些关联用于比较作品、食物、人物或地点之间的联系，具体内容可在下方关联卡片中继续阅读。",
