        "text": "可以先在街区尺度观察建筑与道路、河岸或广场的关系，再靠近看立面、材料、雕塑与使用痕迹。外部观赏、登高和内部参观是不同体验，选择其中最感兴趣的一项，游览会比逐个拍照更有重点。"
