    "note": "这是分布于城市的系列遗产，不是整座卢布尔雅那或全部普列奇尼克作品都自动包含。 卡片通过关联地点继续探索，不用一个坐标冒充所有组成部分。\n\n先确认正式列名的对象与范围，再观察建筑群、自然环境和人类活动怎样组成整体。系列遗产或文化景观可能包含多个区域；卡片的参考点帮助辨认位置，不能代表全部保护范围或所有入口。\n\n“三重桥与普列舍伦广场”：观察桥梁与公共空间；“国家与大学图书馆 · NUK”：从图书馆继续理解设计；“卢布尔雅那中央市场”：看市场与河岸的联系。这些关联用于比较作品、食物、人物或地点之间的联系，具体内容可在下方关联卡片中继续阅读。",
