        "title": "背景与辨别",
        "text": "可以比较原味、无糖和其他版本，不把品牌故事里的传统配方直接等同于每一款今天的配料。 它在邻国也常见，销售范围不代表每个市场都拥有同一生产地点。 地图仅提供附近超市探索，不保证具体商品库存。"
