        "text": "“1867 年妥协：同一君主，两套政府”：回看更早的中欧政治结构；“Slovenija 与 Slovensko：名字相近的两个国家”：辨认今天的国家名称；“鲁道夫·迈斯特 · 马里博尔的 1918 年”：回看更早的边界与人物。这些关联用于比较作品、食物、人物或地点之间的联系，具体内容可在下方关联卡片中继续阅读。"
