        "text": "“布莱德湖 · 东岸步行参考点”：先辨认湖岸尺度；“布莱德城堡”：观察高差与人造建筑；“布莱德湖心岛与圣母教堂”：比较湖与宗教空间。这些关联用于比较作品、食物、人物或地点之间的联系，具体内容可在下方关联卡片中继续阅读。"
