        "text": "“马里博尔城堡与地区博物馆”：从地方历史继续阅读；“1991、2004、2007：几种不同的国家节点”：比较不同时期的国家节点。这些关联用于比较作品、食物、人物或地点之间的联系，具体内容可在下方关联卡片中继续阅读。"
