        "text": "“塔尔蒂尼广场”：认识广场上的纪念；“皮兰为什么会让人想到威尼斯？”：放回出生时的地方背景。这些关联用于比较作品、食物、人物或地点之间的联系，具体内容可在下方关联卡片中继续阅读。"
