        "title": "背景与辨别",
        "text": "先用原文站名查询，再确认运营商、座席与换乘时间。 月票、多日票或区域联票要核对适用范围与实名条件。 跨境路线另查每段实际承运方，购票平台显示路线不等于所有车票已经一并买齐。"
