    "note": "奥得河上的桥梁、河岛、大学与旧城广场构成多层城市景观。二战后的人口与边界变化、今天的文化生活，以及街上的小矮人，都提供不同的阅读入口。\n\n城市铁路出行的重要站点；原文站名用于核对车票、站台和换乘。\n\n城内可能还有其他站点，按具体车次核对实际发到站。 长途车厢、座位和进站时间与城市电车票的规则不同。 坐标用于辨认位置，非精确入口；开放、预约、施工与具体服务按官方最新说明确认。\n\n先核对车票上的完整站名与列车目的地，再看当天站台信息。大城市可能有多个长途站，城市交通站台与铁路站台也可能分属不同空间；把站内步行和换乘余量留在行程里。\n\n“弗罗茨瓦夫 · 到站与换乘”：到站后怎样换乘。这些关联用于比较作品、食物、人物或地点之间的联系，具体内容可在下方关联卡片中继续阅读。",
