        "text": "奥得河上的桥梁、河岛、大学与旧城广场构成多层城市景观。二战后的人口与边界变化、今天的文化生活，以及街上的小矮人，都提供不同的阅读入口。\n\n城市铁路出行的重要站点；原文站名用于核对车票、站台和换乘。"
