    "note": "奥得河上的桥梁、河岛、大学与旧城广场构成多层城市景观。二战后的人口与边界变化、今天的文化生活，以及街上的小矮人，都提供不同的阅读入口。\n\n靠近百年厅的大片城市绿地，适合把建筑与户外空间一起理解。\n\n公园区、日式庭园和其他设施的票务与开放不同；坐标仅为园区参考。 坐标用于辨认位置，非精确入口；开放、预约、施工与具体服务按官方最新说明确认。\n\n从入口到水岸、林荫路或开阔草地，留意不同空间如何被步行者、骑行者和休憩的人使用。与只找一个拍照点相比，选一小段完整步行路线，更能理解公园与周边街区的关系。\n\n“弗罗茨瓦夫 · 河流、气候与日常预算”：把地点放回城市环境；“弗罗茨瓦夫百年厅”：连接现代建筑与公共空间。这些关联用于比较作品、食物、人物或地点之间的联系，具体内容可在下方关联卡片中继续阅读。",
