        "text": "“Pierogi · 波兰饺子”：从菜单练习识别词形；“斯洛文尼亚语的双数，与几句旅行用语”：比较两种斯拉夫语言。这些关联用于比较作品、食物、人物或地点之间的联系，具体内容可在下方关联卡片中继续阅读。"
