        "text": "“爱因斯坦”：比较跨国科学人生；“波兰的 1918 年，为什么不是历史起点？”：把出生与成长放回历史背景。这些关联用于比较作品、食物、人物或地点之间的联系，具体内容可在下方关联卡片中继续阅读。"
